// src/services/core/token.service.ts
import crypto from "crypto";
import { TempToken, ITempToken } from "../../models/temp-token.model";
import { logger as rootLogger } from "../logging";
import { SignJWT, importPKCS8 } from "jose";
import { appService } from "./app.service";

const logger = rootLogger.child({ service: "temp-token.service" });

/**
 * `.env` files store PEMs as a single quoted line with literal `\n`
 * sequences. `process.env` returns those backslash-n pairs verbatim, but
 * `importPKCS8` rejects them — it expects real newlines. Normalize so
 * either form (multi-line PEM or escaped single line) works.
 */
function normalizePemFromEnv(value: string): string {
  return value.replace(/\\r/g, "").replace(/\\n/g, "\n").trim();
}

const RAW_PRIVATE_KEY: string | null =
  process.env.APP_AUTH_JWT_PRIVATE_KEY ||
  process.env.TPA_AUTH_JWT_PRIVATE_KEY ||
  null;

/**
 * Exported as the normalized env value for back-compat with anything that
 * imported it before. New code should not consume this directly — call
 * `tokenService.issueUserToken` and let the cached key path handle it.
 */
export const APP_AUTH_JWT_PRIVATE_KEY: string | null = RAW_PRIVATE_KEY
  ? normalizePemFromEnv(RAW_PRIVATE_KEY)
  : null;

if (!APP_AUTH_JWT_PRIVATE_KEY) {
  logger.warn(
    "[token.service] APP_AUTH_JWT_PRIVATE_KEY is not set — issueUserToken() will fail until it's configured.",
  );
}

const SIGNING_ALG = "RS256";
const TOKEN_ISSUER = process.env.APP_AUTH_JWT_ISSUER || "https://prod.augmentos.cloud";

/**
 * Cache the imported private key. `importPKCS8` parses the PEM and returns
 * a CryptoKey — that work shouldn't repeat on every call. We cache the
 * promise so concurrent callers share one import. We use the inferred
 * return type of `importPKCS8` instead of a named `KeyLike` (which jose
 * removed in recent versions).
 */
type PrivateKey = Awaited<ReturnType<typeof importPKCS8>>;
let cachedPrivateKey: Promise<PrivateKey> | null = null;

function loadPrivateKey(): Promise<PrivateKey> {
  if (cachedPrivateKey) return cachedPrivateKey;
  if (!APP_AUTH_JWT_PRIVATE_KEY) {
    return Promise.reject(
      new Error(
        "[token.service] APP_AUTH_JWT_PRIVATE_KEY is not set. Add a PKCS8 RSA private key to the cloud .env (multiline or single-line with \\n escapes both work).",
      ),
    );
  }
  cachedPrivateKey = importPKCS8(APP_AUTH_JWT_PRIVATE_KEY, SIGNING_ALG).catch((err) => {
    // Don't keep a poisoned cache — let the next call retry, in case
    // the operator hot-edits the env (e.g. via docker-compose restart).
    cachedPrivateKey = null;
    const detail = err instanceof Error ? err.message : String(err);
    throw new Error(
      `[token.service] Failed to import APP_AUTH_JWT_PRIVATE_KEY as PKCS8 RSA: ${detail}. ` +
        `Confirm the value is a "-----BEGIN PRIVATE KEY-----" block and that newlines are real \\n or actual line breaks.`,
    );
  });
  return cachedPrivateKey;
}

// Eagerly verify the key at startup so misconfig surfaces immediately
// instead of on the first webview launch. Failure here only logs — we don't
// crash the cloud, since not every install needs JWT issuance.
if (APP_AUTH_JWT_PRIVATE_KEY) {
  loadPrivateKey()
    .then(() => logger.info("[token.service] APP_AUTH_JWT_PRIVATE_KEY loaded and ready for RS256 signing"))
    .catch((err) =>
      logger.error(
        { err: err instanceof Error ? err.message : String(err) },
        "[token.service] APP_AUTH_JWT_PRIVATE_KEY is set but failed to import",
      ),
    );
}

/**
 * Interface for the result of exchanging a temporary token
 */
interface ExchangeTokenResult {
  userId: string;
}

/**
 * Service for managing temporary tokens and user authentication tokens.
 * Handles token generation, exchange, and JWT signing operations.
 */
export class TokenService {
  /**
   * Generates a secure temporary token and stores it in the database.
   * The token expires after 60 seconds and can only be used once.
   *
   * @param userId - The user ID associated with the token
   * @param packageName - The package name of the App this token is intended for
   * @returns Promise resolving to the generated temporary token string
   * @throws Error if token generation or storage fails
   */
  async generateTemporaryToken(
    userId: string,
    packageName: string,
  ): Promise<string> {
    const logger = rootLogger.child({
      service: "temp-token.service",
      userId,
      packageName,
    });

    // Generate a cryptographically secure random token
    const token: string = crypto.randomBytes(32).toString("hex");

    const tempTokenDoc = new TempToken({
      token,
      userId,
      packageName,
      createdAt: new Date(), // Explicitly set createdAt for clarity, though default works
      // Note: MongoDB TTL index handles expiration based on 'createdAt' field
    });

    try {
      await tempTokenDoc.save();
      logger.info(
        `Generated temporary token for user ${userId} and package ${packageName}`,
      );
      return token;
    } catch (error) {
      {
        const err = error instanceof Error ? error : new Error(String(error));
        logger.error(
          err,
          `Error saving temporary token for user ${userId}, package ${packageName}:`,
        );
      }
      throw new Error("Failed to generate temporary token");
    }
  }

  /**
   * Exchanges a temporary token for the associated user ID, validating the requesting App.
   * Performs multiple security checks:
   * - Token existence and validity
   * - Single-use enforcement (marks token as used)
   * - Expiration check (60-second TTL)
   * - Package name validation (prevents cross-App token usage)
   *
   * @param tempToken - The temporary token string to exchange
   * @param requestingPackageName - The package name of the App making the exchange request
   * @returns Promise resolving to an object containing the userId if valid, null otherwise
   */
  async exchangeTemporaryToken(
    tempToken: string,
    requestingPackageName: string,
  ): Promise<ExchangeTokenResult | null> {
    const logger = rootLogger.child({
      service: "temp-token.service",
      requestingPackageName,
      tempToken,
    });
    try {
      const tokenDoc: ITempToken | null = await TempToken.findOne({
        token: tempToken,
      });

      if (!tokenDoc) {
        logger.warn({ tempToken, requestingPackageName }, "Temporary token not found");
        return null;
      }

      // Order checks so that the most useful diagnostic wins. Package
      // mismatch is checked before "already used" because mismatch is a
      // security signal we want surfaced even if the token was already
      // consumed by the rightful app.
      if (tokenDoc.packageName !== requestingPackageName) {
        logger.error(
          {
            tokenPackage: tokenDoc.packageName,
            requestingPackageName,
            tempToken,
          },
          "Token package mismatch — rejecting exchange",
        );
        return null;
      }

      // Expired (>60s)? TTL index also handles this, but check explicitly
      // so we can log it.
      const tokenAgeInMs = Date.now() - new Date(tokenDoc.createdAt).getTime();
      if (tokenAgeInMs > 60000) {
        logger.warn({ tempToken, tokenAgeInMs }, "Temporary token expired");
        return null;
      }

      // Idempotent exchange within TTL. The `used` flag is defense against
      // *another* package replaying the token — a check the package guard
      // above already enforces. React StrictMode and flaky webview reloads
      // routinely fire the same /init call twice, so rejecting the second
      // attempt strands the user in "Not authenticated" for no security
      // gain. We instead allow the rightful package to re-exchange the
      // same token any number of times within its 60s lifetime.
      const wasAlreadyUsed = tokenDoc.used === true;
      if (!wasAlreadyUsed) {
        tokenDoc.used = true;
        await tokenDoc.save();
      }

      logger.info(
        {
          userId: tokenDoc.userId,
          requestingPackageName,
          replay: wasAlreadyUsed,
          tokenAgeInMs,
        },
        wasAlreadyUsed
          ? "Re-exchanged temporary token (within TTL, same package — likely StrictMode/retry)"
          : "Exchanged temporary token",
      );
      return { userId: tokenDoc.userId };
    } catch (error) {
      {
        const err = error instanceof Error ? error : new Error(String(error));
        logger.error(err, `Error exchanging temporary token ${tempToken}:`);
      }
      return null; // Return null on any error during exchange
    }
  }

  /**
   * Issues a signed JWT token for AugmentOS users to be used in App webviews.
   * The token contains:
   * - User ID in the 'sub' claim
   * - Frontend token in the format 'userId:hash' where hash is created using the app's API key
   *
   * The frontend token can be verified by the App using their API key to ensure authenticity.
   *
   * @param aosUserId - The AugmentOS user ID to include in the token
   * @param packageName - The package name of the App to generate the frontend token for
   * @returns Promise resolving to a signed JWT token string
   * @throws Error if private key is not configured or token generation fails
   */
  async issueUserToken(aosUserId: string, packageName: string): Promise<string> {
    try {
      // Cached PKCS8 RSA key, with `\n`-escaped envs already normalized.
      const privateKey = await loadPrivateKey();

      // Frontend token uses the app's API-key hash instead of a shared
      // secret, so the App can verify it with its own API key.
      const frontendTokenHash: string = await appService.hashWithApiKey(aosUserId, packageName);

      const token: string = await new SignJWT({
        sub: aosUserId,
        frontendToken: `${aosUserId}:${frontendTokenHash}`,
      })
        .setProtectedHeader({ alg: SIGNING_ALG, kid: "v1" })
        .setIssuer(TOKEN_ISSUER)
        .setIssuedAt()
        .setExpirationTime("10m")
        .sign(privateKey);
      return token;
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      logger.error({ err: detail, aosUserId, packageName }, "[token.service] Failed to issue user token");
      // Surface the underlying cause in the thrown error so callers (and
      // ops dashboards) can distinguish "key missing" from "JWT sign failed".
      throw new Error(`[token.service] Failed to generate signed user token: ${detail}`);
    }
  }
}

export const tokenService = new TokenService();
